{
  "primary_meaning": "Satan/the Devil as the embodiment of evil, deception, and temptation",
  "primary_basis": [
    "Genesis 3 (serpent as tempter of Eve)",
    "Revelation 12:9 (ancient serpent identified as the devil/Satan)",
    "Revelation 20:2 (dragon/ancient serpent bound as Satan)",
    "2 Corinthians 11:3 (serpent's cunning deception of Eve)"
  ],
  "alternatives": [
    {
      "meaning": "Literal animal or natural creature without necessary demonic identification",
      "basis": [
        "Genesis 3 read in historical-critical isolation",
        "Absence of explicit Satan language in the Hebrew text of Genesis"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Symbol of wisdom, shrewdness, or prudent cunning (sometimes positive)",
      "basis": [
        "Matthew 10:16 ('wise as serpents')",
        "Proverbs 30:18-19 (serpent on a rock as wonder)",
        "Ancient Near Eastern associations of serpents with wisdom"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Typological prefiguration of Christ and salvation/healing (bronze serpent)",
      "basis": [
        "Numbers 21:4-9 (bronze serpent raised for healing)",
        "John 3:14-15 (Son of Man lifted up like the serpent)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Chaos monster or primordial force of disorder (linked to Leviathan/Rahab imagery)",
      "basis": [
        "Isaiah 27:1",
        "Psalm 74:13-14",
        "Job 26:13 and related chaoskampf motifs"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Agent of enlightenment or liberator of knowledge (non-orthodox/Gnostic readings)",
      "basis": [
        "Gnostic reinterpretations of Genesis 3",
        "Select modern esoteric or revisionist treatments"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "In mainstream Christian teaching and traditional biblical interpretation the identification of the Genesis serpent with Satan is the long-settled dominant reading, reinforced by New Testament explicit equations. Alternative senses appear in specific textual contexts (bronze serpent, shrewdness sayings) or in critical/Gnostic scholarship, but do not displace the primary Satanic symbolism in Christian consensus."
}
